{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.shinpr/sub-agents-mcp",
  "description": "MCP server for AI sub-agent delegation across Cursor, Claude, Codex, Gemini, GLM, and Grok",
  "vendor": "Shinsuke Kagawa",
  "license": "MIT",
  "repository": {
    "url": "https://github.com/shinpr/sub-agents-mcp",
    "source": "github"
  },
  "version": "0.10.0",
  "packages": [
    {
      "registryType": "npm",
      "registryBaseUrl": "https://registry.npmjs.org",
      "identifier": "sub-agents-mcp",
      "version": "0.10.0",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "AGENTS_DIR",
          "description": "Absolute path to the directory containing agent definition files (.md or .txt)",
          "isRequired": true,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "AGENT_TYPE",
          "description": "Type of AI CLI to use: 'cursor', 'claude', 'gemini', 'codex', 'glm', or 'grok'",
          "isRequired": true,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "AGENT_PERMISSION",
          "description": "Approval/sandbox level for sub-agents: 'read-only', 'safe-edit' (default), or 'yolo'",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "CURSOR_API_KEY",
          "description": "API key for cursor-agent authentication (used only when AGENT_TYPE=cursor; passed via env, never via CLI args)",
          "isRequired": false,
          "format": "string",
          "isSecret": true
        },
        {
          "name": "CLI_API_KEY",
          "description": "Z.ai API token for AGENT_TYPE=glm (passed to the claude binary via env, never via CLI args). Restart/reconnect the MCP server after changing it.",
          "isRequired": false,
          "format": "string",
          "isSecret": true
        },
        {
          "name": "EXECUTION_TIMEOUT_MS",
          "description": "Maximum execution time for agents in milliseconds (default: 300000, max: 600000)",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "SESSION_ENABLED",
          "description": "Enable session management to maintain execution history across agent calls (default: false)",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "SESSION_DIR",
          "description": "Directory path for storing session files (default: .mcp-sessions in current working directory)",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "SESSION_RETENTION_DAYS",
          "description": "Number of days to retain session history before automatic cleanup (default: 7)",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "AGENTS_SETTINGS_PATH",
          "description": "Path to CLI settings file/directory. Claude: --settings arg, Cursor: CURSOR_CONFIG_DIR, Codex: CODEX_HOME. Gemini/Grok not supported.",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        }
      ],
      "features": {
        "tools": {
          "supported": true,
          "list": [
            "run_agent"
          ]
        },
        "prompts": {
          "supported": false
        },
        "resources": {
          "supported": true
        }
      }
    }
  ],
  "tags": [
    "mcp",
    "mcp-server",
    "model-context-protocol",
    "sub-agents",
    "ai-agents",
    "claude-code",
    "cursor",
    "gemini",
    "codex",
    "glm",
    "z.ai",
    "grok",
    "llm",
    "cli",
    "agent-orchestration"
  ],
  "homepage": "https://github.com/shinpr/sub-agents-mcp",
  "documentation": "https://github.com/shinpr/sub-agents-mcp#readme"
}
